#include "stdlib/stats/base/ndarray/smskrange.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include <stdint.h>

/**
* Compute the range of a one-dimensional single-precision floating-point ndarray according to a mask.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional mask ndarray.
*
* @param arrays    list containing ndarrays
* @return          range
*/
float stdlib_stats_smskrange( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *mask = arrays[ 1 ];

	int64_t n = stdlib_ndarray_dimension( x, 0 );
	if ( n <= 0 ) {
		return 0.0f / 0.0f; // NaN
	}

	const float *X = (const float *)stdlib_ndarray_data( x );
	const uint8_t *Mask = (const uint8_t *)stdlib_ndarray_data( mask );

	int64_t strideX = stdlib_ndarray_stride_elements( x, 0 );
	int64_t offsetX = stdlib_ndarray_offset_elements( x );

	int64_t strideMask = stdlib_ndarray_stride_elements( mask, 0 );
	int64_t offsetMask = stdlib_ndarray_offset_elements( mask );

	float max_val = -1.0f / 0.0f; // -Infinity
	float min_val = 1.0f / 0.0f;  // +Infinity
	int has_unmasked = 0;
	
	int64_t ix = offsetX;
	int64_t im = offsetMask;

	for ( int64_t i = 0; i < n; i++ ) {
		if ( Mask[ im ] == 0 ) {
			float v = X[ ix ];
			if ( stdlib_base_is_nanf( v ) ) {
				return 0.0f / 0.0f; // NaN
			}
			if ( v > max_val ) {
				max_val = v;
			}
			if ( v < min_val ) {
				min_val = v;
			}
			has_unmasked = 1;
		}
		ix += strideX;
		im += strideMask;
	}

	if ( !has_unmasked ) {
		return 0.0f / 0.0f; // NaN
	}
	return max_val - min_val;
}
